#define MAX_STEPS 100
#define MAX_DIST   50.0
#define EPSILON    0.001

float sdSphere(vec3 p, float r)
{
    return length(p) - r;
}

float sdPlane(vec3 p)
{
    return p.y;
}

float opU(float d1, float d2){ return min(d1, d2); }

float mapScene(vec3 p)
{
    float dSphere = sdSphere(p - vec3(0,1,2), 1.0);
    float dPlane = sdPlane(p);
    return opU(dSphere, dPlane);
}

vec3 calcNormal(vec3 p)
{
    float d = mapScene(p);
    vec2 e = vec2(0.002, 0);
    vec3 n;
    n.x = mapScene(p + vec3(e.x, e.y, e.y)) - d;
    n.y = mapScene(p + vec3(e.y, e.x, e.y)) - d;
    n.z = mapScene(p + vec3(e.y, e.y, e.x)) - d;
    return normalize(n);
}


float rayMarch(vec3 ro, vec3 rd)
{
    float t = 0.0;
    for (int i = 0; i < MAX_STEPS; i++)
    {
        vec3 p = ro + rd * t;
        float d = mapScene(p);
        if(d < EPSILON) 
            return t;
        t += d;
        if(t > MAX_DIST) 
            break;
    }
    return -1.0;
}


vec3 triPlanarTexture(vec3 p, vec3 n)
{
    vec3 an = abs(n);

    float sum = an.x + an.y + an.z + 1e-8;

    float scale = 0.7;
    vec2 uvx = p.zy * 0.5 * scale;  
    vec2 uvy = p.xz * 0.5 * scale;  
    vec2 uvz = p.xy * 0.5 * scale;  
    vec3 tx = texture(iChannel0, uvx).rgb; 
    vec3 ty = texture(iChannel0, uvy).rgb;
    vec3 tz = texture(iChannel0, uvz).rgb;

    vec3 color = (tx * an.x + ty * an.y + tz * an.z) / sum;
    return color;
}


vec3 lighting(vec3 p, vec3 ro, vec3 rd)
{
    vec3 n = calcNormal(p);

    vec3 lightPos   = vec3(3.0,4.0,1.0);
    vec3 lightColor = vec3(1.0);

    vec3 L = normalize(lightPos - p);
    float diff = max(dot(n, L), 0.0);

    vec3 R = reflect(-L, n);
    float spec = pow(max(dot(R, -rd), 0.0), 16.0);

    float shadow = 1.0;
    {
        float tToLight = rayMarch(p + n*EPSILON*2.0, L);
        float distLight = length(lightPos - p);
        if (tToLight>0. && tToLight<distLight) 
            shadow = 0.3;
    }

    vec3 baseColor = triPlanarTexture(p, n);
    vec3 lightSum = lightColor * (diff + spec) * shadow;
    vec3 ambient = vec3(0.40);

    vec3 colorNoReflect = baseColor * (ambient + lightSum);
    float NdotV = dot(n, -rd);
    float fresnel = pow(1.0 - NdotV, 5.0);
    vec3 reflectionColor = texture(iChannel1, reflect(rd, n)).rgb;
    float reflectFactor = mix(0.04, 1.0, fresnel) - 0.05;

    vec3 finalColor = mix(colorNoReflect, reflectionColor, reflectFactor);

    return finalColor;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    float time = iTime * 0.3;
    float radius = 3.5;

    vec3 ro = vec3(sin(time)*radius, 1.5, cos(time)*radius);
    vec3 center = vec3(0,1,2);

    vec3 cw = normalize(center - ro);
    vec3 cr = normalize(cross(vec3(0,1,0), cw));
    vec3 cu = cross(cw, cr);
    vec3 rd = normalize(uv.x*cr + uv.y*cu + cw);

    float t = rayMarch(ro, rd);

    if(t < 0.0)
    {

        vec3 skyColor = texture(iChannel1, rd).rgb; 
        fragColor = vec4(skyColor, 1.0);
        return;
    }

    vec3 p = ro + rd * t;
    vec3 col = lighting(p, ro, rd);

    col = pow(col, vec3(1.0/2.2));
    fragColor = vec4(col, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float t = iTime * 0.3;

    float r = length(uv);
    float a = atan(uv.y, uv.x) + r * 3.0 - t;
    uv = r * vec2(cos(a), sin(a));

    float scale = 5.0;
    float checker = step(0.0, sin(uv.x*scale)*sin(uv.y*scale));

    vec3 colorA = vec3(0.8, 0.2, 0.2);
    vec3 colorB = vec3(0.9, 0.9, 0.9);
    vec3 col = mix(colorA, colorB, checker);

    col *= smoothstep(1.0, 0.3, r);

    fragColor = vec4(col, 1.0);
}
